            nloop = lo & 0x7fff; flg = (lo >> 58) & 3; nreg = (lo >> 60) & 15 or 16
            pl = nloop * nreg * 16 if flg == 0 else (((nloop * nreg + 1) // 2) * 16 if flg == 1 else (nloop * 16 if flg == 2 else 0))
